# quasicrystal.py — roadmap item 4: numerically demonstrate his conjecture that
# non-minimal lasers in general position give quasicrystals, via the rank
# criterion: the potential is periodic iff the Z-module generated by the
# difference vectors {k_1l} has rank = d over the integers.
import numpy as np, json
from itertools import combinations

root = '/private/tmp/claude-501/-Users-mike-Documents-Claude/325cb1ea-d772-429f-8fbb-7d3ef2b01dc0/scratchpad'

def potential_2d(kvecs, L=60.0, N=900):
    """V(x) = sum over laser pairs of cos((k_j-k_l).x), unit amplitudes."""
    x = np.linspace(-L/2, L/2, N)
    X, Y = np.meshgrid(x, x, indexing='ij')
    V = np.zeros_like(X)
    for (j, l) in combinations(range(len(kvecs)), 2):
        kd = kvecs[j] - kvecs[l]
        V += np.cos(kd[0]*X + kd[1]*Y)
    return V

def rank_over_Z(diffs, tol=1e-9):
    """Rational rank of the module generated by difference vectors: build the
    matrix of all k_1l expressed in an LLL-ish basis — here simply the rank of
    the real matrix vs the count of rationally independent rows (numeric proxy:
    rank of the matrix over R of the generators AND of integer relations)."""
    M = np.array(diffs)
    # real rank
    r_real = np.linalg.matrix_rank(M, tol=1e-8)
    # rational rank: number of generators modulo integer relations — detect by
    # checking if any generator is an integer combination of a maximal
    # independent subset (solve least squares, test integrality)
    # Z-module rank = Q-linear rank of the generators: v adds no rank iff it is
    # a RATIONAL combination of the current basis. HEURISTIC, with two
    # documented limits (round-4 review): (1) rationality is tested against a
    # maximal REAL-linearly-independent subset, which can over-count rank for
    # redundant generator sets once module rank exceeds the spatial dimension;
    # (2) only denominators up to 64 are scanned. Exact certification for
    # general inputs needs lattice reduction (LLL/PSLQ). The four
    # configurations in this script are standard, non-redundant sets whose
    # module ranks are known analytically; the heuristic agrees with those.
    basis = []
    for v in M:
        if not basis:
            basis.append(v); continue
        B = np.array(basis).T
        # exact solve on an independent column subset (avoids min-norm)
        q, r, piv = __import__('scipy.linalg', fromlist=['qr']).qr(B, pivoting=True)
        rk = int((np.abs(np.diag(r)) > 1e-10).sum())
        Bi = B[:, piv[:rk]]
        coef, res, *_ = np.linalg.lstsq(Bi, v, rcond=None)
        in_span = np.linalg.norm(Bi @ coef - v) < 1e-8
        rational = in_span and any(
            np.allclose(coef * t, np.round(coef * t), atol=1e-6) for t in range(1, 65))
        if rational:
            continue                      # rational combination: no new rank
        basis.append(v)
    return r_real, len(basis)

results = {}

# Case 1: minimal 2D config (3 lasers) -> true lattice (his theorem, base case)
k3 = [np.array([np.cos(a), np.sin(a)]) for a in (0.3, 2.1, 4.0)]
diffs3 = [k3[0]-k3[1], k3[0]-k3[2]]
r_real, r_mod = rank_over_Z(diffs3)
results['minimal_3laser'] = dict(rank_real=int(r_real), rank_module=int(r_mod),
                                 periodic=bool(r_mod == 2))
V3 = potential_2d(k3)

# Case 2: 5 lasers, pentagonal (general position) -> 10-fold quasicrystal
k5 = [np.array([np.cos(2*np.pi*j/5), np.sin(2*np.pi*j/5)]) for j in range(5)]
diffs5 = [k5[0]-k5[j] for j in range(1, 5)]
r_real, r_mod = rank_over_Z(diffs5)
results['pentagonal_5laser'] = dict(rank_real=int(r_real), rank_module=int(r_mod),
                                    periodic=bool(r_mod == 2))
V5 = potential_2d(k5)

# Case 3: 4 lasers arranged so differences ARE on a lattice (his countable
# family of non-minimal lattice configs): square lattice + one redundant laser
b1, b2 = np.array([1., 0.]), np.array([0., 1.])
v0 = np.array([0.35, 0.8])                     # arbitrary base k
k4 = [v0, v0+b1, v0+b2, v0+b1+2*b2]            # 4th is integer combo -> lattice
diffs4 = [k4[0]-k4[j] for j in range(1, 4)]
r_real, r_mod = rank_over_Z(diffs4)
results['redundant_4laser'] = dict(rank_real=int(r_real), rank_module=int(r_mod),
                                   periodic=bool(r_mod == 2))
V4 = potential_2d(k4, L=40.0)

# Diffraction (structure factor) of the pentagonal case: 10-fold Bragg peaks
F5 = np.abs(np.fft.fftshift(np.fft.fft2(V5)))**2
F3 = np.abs(np.fft.fftshift(np.fft.fft2(V3)))**2

# 3D icosahedral: 6 five-fold axes of the icosahedron -> rank-6 module in 3D
phi = (1 + np.sqrt(5)) / 2
ico = np.array([[1, phi, 0], [1, -phi, 0], [0, 1, phi],
                [0, 1, -phi], [phi, 0, 1], [-phi, 0, 1]])
ico = ico / np.linalg.norm(ico[0])
r_real, r_mod = rank_over_Z(list(ico))
results['icosahedral_3d'] = dict(rank_real=int(r_real), rank_module=int(r_mod),
                                 periodic=bool(r_mod == 3))
# a 2D slice of the 3D icosahedral potential for display
L, N = 60.0, 700
x = np.linspace(-L/2, L/2, N)
X, Y = np.meshgrid(x, x, indexing='ij')
Vico = np.zeros_like(X)
for k in ico:
    Vico += np.cos(k[0]*X + k[1]*Y)            # z=0 slice
np.savez(f'{root}/quasicrystal.npz', V3=V3, V5=V5, V4=V4, Vico=Vico, F5=F5, F3=F3)
for name, r in results.items():
    verdict = 'LATTICE (periodic)' if r['periodic'] else f"QUASICRYSTAL (module rank {r['rank_module']} > d)"
    print(f"{name:22s} rank_real={r['rank_real']} rank_module={r['rank_module']}  -> {verdict}")
json.dump(results, open(f'{root}/quasicrystal.json', 'w'))
